/**
 * Creates the README.md content for the compiled output.
 *
 * The README tells coding agents what this generated folder is, what to edit
 * instead, and where inlang tooling ends and Paraglide JS begins.
 * See https://llmstxt.org/ for the format guidelines.
 */
export declare function createReadme(args: {
    projectPath?: string;
    /** Whether the output also contains a `.gitignore` that ignores it. */
    gitignored?: boolean;
}): string;
